from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[1];A=ROOT/'public/assets/exotic'
items=[]
rec={'scene-wedding-portal','portal-arch-triple','floral-centerpiece','sculptural-ribbon','wedding-rings','navratri','hospitality','exotic-emblem-reveal','exotic-emblem-orbit','booking-success','divider-botanical','gold-ribbon-wide','floral-corner-left','studio-softbox','logo-transparent-native'}
def path(p):return str(p.relative_to(ROOT))
for m in json.loads((ROOT/'models-manifest.json').read_text()):
 name=m['id'];items.append({'id':name,'category':'models','title':m['title'],'src':m['path'],'image':path(A/'model-thumbnails'/f'{name}.webp'),'secondary':m['mobilePath'],'secondaryLabel':'Lighter GLB','details':f"{m['triangles']:,} triangles · {m['mobileTriangles']:,} lighter variant",'inspect':True,'recommended':name in rec})
for p in sorted((A/'models/animated').glob('*.glb')):
 items.append({'id':p.stem+'-animated','category':'animated models','title':p.stem.replace('-',' ').title()+' · clip','src':path(p),'image':path(A/'model-thumbnails'/f'{p.stem}.webp'),'details':'GLB with an embedded transform animation','inspect':True})
for p in sorted((A/'icons/gold').glob('*.svg')):
 items.append({'id':p.stem+'-icon','category':'icons','title':p.stem.replace('-',' ').title(),'src':path(p),'image':path(p),'secondary':path(A/'icons/current-color'/p.name),'secondaryLabel':'currentColor SVG','details':'Original 24 × 24 stroke SVG · two color treatments','recommended':p.stem in rec})
for a in json.loads((ROOT/'lottie-manifest.json').read_text()):
 name=a['id'];items.append({'id':name,'category':'motion','title':a['title'].replace('Exotic / ',''),'src':a['path'],'image':path(A/'lottie-posters'/f'{name}.png'),'secondary':path(A/'animated-svg'/f'{name}.svg'),'secondaryLabel':'Animated SVG','details':f"4 seconds · {'Loop option' if a['loopRecommended'] else 'Play once'} · JSON + SVG alternative",'animation':path(A/'animated-svg'/f'{name}.svg'),'recommended':name in rec})
for p in sorted((A/'ornaments').glob('*.svg')):
 items.append({'id':p.stem,'category':'ornaments','title':p.stem.replace('-',' ').title(),'src':path(p),'image':path(p),'secondary':path(p.with_suffix('.png')),'secondaryLabel':'PNG','details':'Editable vector + transparent raster alternative','recommended':p.stem in rec})
for cat,folder,glob in [('overlays','overlays','*.png'),('textures','textures','*.png'),('backgrounds','backgrounds','*.webp')]:
 for p in sorted((A/folder).glob(glob)):
  items.append({'id':p.stem,'category':cat,'title':p.stem.replace('-',' ').title(),'src':path(p),'image':path(p),'details':'Transparent foreground layer' if cat=='overlays' else 'Original texture / data map' if cat=='textures' else 'Text-free 3D concept illustration; not a client photograph','recommended':p.stem in rec})
items.append({'id':'studio-softbox','category':'textures','title':'Studio softbox HDR','src':path(A/'textures/studio-softbox.hdr'),'image':path(A/'textures/studio-softbox-preview.png'),'details':'Original .hdr lighting environment · optional','recommended':True})
for p in sorted((A/'logos').glob('*')):
 if p.is_file():items.append({'id':p.stem,'category':'brand','title':p.stem.replace('-',' ').title(),'src':path(p),'image':path(p),'details':'Approximate silhouette trace, not master vector' if p.suffix=='.svg' else 'Derivative of the supplied low-resolution logo' if 'original' not in p.stem else 'Supplied source raster','recommended':p.stem in rec})
for p in sorted((ROOT/'references').glob('*.png')):items.append({'id':'ref-'+p.stem,'category':'references','title':p.stem.replace('_',' ').title(),'src':path(p),'image':path(p),'details':'Earlier AI-generated mockup · visual reference only; claims unverified'})
# Use compact raster thumbnails in cards; originals remain available via source links.
from PIL import Image
thumbs=ROOT/'previews/asset-thumbnails';thumbs.mkdir(exist_ok=True)
for item in items:
 image=ROOT/item['image']
 if image.suffix.lower() in ['.png','.jpg','.webp'] and image.stat().st_size>100000:
  img=Image.open(image);img.thumbnail((480,480))
  name=item['category'].replace(' ','-')+'-'+item['id']+'.webp'
  img.save(thumbs/name,quality=85)
  item['image']=str((thumbs/name).relative_to(ROOT))
DATA=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
htmlpage='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exotic | Asset library</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#0b100d;color:#f1ebdd;font:15px/1.6 system-ui,-apple-system,sans-serif}button,a,input,select{font:inherit}a{color:#dfc381;text-decoration:none}a:hover{text-decoration:underline}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #edd69a;outline-offset:4px}.wrap{max-width:1440px;margin:auto;padding:0 48px}header{padding:32px 0;border-bottom:1px solid #293226}header .wrap{display:flex;justify-content:space-between;align-items:center;gap:24px}.brand{letter-spacing:.22em;color:#d6b76b;font-size:12px}header a{margin-left:24px;font-size:13px}.intro{padding-top:60px;padding-bottom:48px}.intro h1{font:clamp(38px,5vw,65px)/1.1 Georgia,serif;max-width:950px;margin:17px 0 24px;letter-spacing:-.035em}.intro p{max-width:850px;color:#aeb6a6;font-size:17px}.stats{display:flex;gap:46px;flex-wrap:wrap;margin:34px 0 0}.stats strong{font:36px Georgia;color:#e8d6a5;display:block}.stats span{font-size:12px;color:#aab29f}.note{border-left:2px solid #b5944d;padding:12px 18px;color:#c4c9bb;background:#151d16;font-size:13px;margin:28px 0 0}.toolbar{position:sticky;top:0;z-index:10;background:#0b100df5;backdrop-filter:blur(8px);border-block:1px solid #293226;padding:20px 0}.controls{display:flex;gap:12px;flex-wrap:wrap}.controls input{flex:1;min-width:190px}input,select{background:#172019;color:#ede9da;border:1px solid #3b4935;border-radius:8px;padding:12px 15px}.pill{color:#edd9a5;background:none;border:1px solid #74643f;border-radius:30px;padding:10px 17px;white-space:nowrap}.primary{background:#d6b76b;color:#13170f;border-color:#d6b76b}.summary{font-size:12px;letter-spacing:.08em;color:#9da892;padding:24px 0 18px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;padding-bottom:70px}.card{border:1px solid #2b3728;border-radius:16px;overflow:hidden;background:#141d16;display:flex;flex-direction:column}.art{height:230px;position:relative;background:radial-gradient(ellipse at 50% 70%,#233023,#121a14);display:flex;align-items:center;justify-content:center}.art img{width:90%;height:90%;object-fit:contain}.card[data-category="icons"] .art img{width:72px;height:72px}.card[data-category="references"] .art img{width:100%;height:100%;object-fit:contain}.card[data-category="textures"] .art img,.card[data-category="backgrounds"] .art img{width:100%;height:100%;object-fit:cover}.badge{position:absolute;top:12px;left:12px;font-size:10px;letter-spacing:.1em;color:#e9dcae;background:#0b100dc9;border:1px solid #60563c;padding:3px 8px;border-radius:30px}.body{padding:20px;flex:1;display:flex;flex-direction:column}.body h2{font:21px/1.22 Georgia;margin:0 0 10px}.body p{margin:0;color:#a3ae99;font-size:12px;min-height:40px}.links{display:flex;gap:10px;flex-wrap:wrap;font-size:12px;margin-top:16px}.links a{padding:5px 0}.bottom{display:flex;gap:10px;flex-wrap:wrap;margin-top:auto;padding-top:18px}.small{border:1px solid #4f5a42;background:transparent;color:#d3dacb;border-radius:20px;padding:6px 12px;font-size:11px}.small[aria-pressed="true"]{background:#d6b76b;color:#111711;border-color:#d6b76b}.play{position:absolute;bottom:12px;right:12px;background:#0b100d}.empty{font:24px Georgia;padding:30px}.footer{padding:45px 0;border-top:1px solid #293226;color:#a8b19d;font-size:13px}.footer a{display:inline-block;margin-right:20px}.files-note{font-size:12px;color:#a6af9c;margin:12px 0}.notice{color:#e9d5a0;font-size:12px}
@media(max-width:1080px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}.wrap{padding-inline:28px}.stats{gap:25px}}@media(max-width:760px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.wrap{padding-inline:20px}header .wrap{align-items:flex-start;flex-direction:column}header a{margin:0 18px 0 0}.intro{padding-top:35px}.art{height:190px}.body{padding:15px}.body h2{font-size:19px}.stats strong{font-size:29px}.toolbar{position:relative}}@media(max-width:430px){.art{height:150px}.controls>*{width:100%}.body h2{font-size:17px}.body p{font-size:11px}.stats{gap:20px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
</style></head><body><header><div class="wrap"><div class="brand">EXOTIC / THE ASSET LIBRARY</div><nav><a href="BUILD_PROMPT.md">Build prompt</a><a href="ASSET_MAP.md">What to use where</a><a href="README.md">Read me</a></nav></div></header><main><section class="wrap intro"><div class="brand">A SOURCE LIBRARY. NOT JUST A MOODBOARD.</div><h1>Choose the detail.<br>Create the feeling.</h1><p>Original geometry, thoughtful vector details and restrained motion. Browse the collection, shortlist the pieces that fit, and let everything else stay in the library.</p><div class="stats"><div><strong>35</strong><span>3D MODEL / SCENE DESIGNS</span></div><div><strong>52</strong><span>ICON DESIGNS · TWO TREATMENTS</span></div><div><strong>14</strong><span>LOTTIE ANIMATIONS + SVG OPTIONS</span></div><div><strong>4</strong><span>GLB ANIMATED COUNTERPARTS</span></div></div><div class="note">The source models and animations are newly built stylized assets. Earlier generated mockups are preserved as references, not verified portfolio work or editable source files. Select what suits the page; do not deploy the entire library at once.</div></section><section class="toolbar"><div class="wrap"><div class="controls"><input id="search" placeholder="Search arches, hospitality, loader…" aria-label="Search assets"><select id="category" aria-label="Asset category"><option value="recommended">Recommended shortlist</option><option value="all">All designs</option><option value="models">3D models / scenes</option><option value="animated models">Animated GLB variants</option><option value="motion">Lottie / SVG animation</option><option value="icons">SVG icons</option><option value="ornaments">Ornaments</option><option value="overlays">PNG overlays</option><option value="textures">Textures / HDR</option><option value="backgrounds">3D backgrounds</option><option value="brand">Logo / brand</option><option value="references">Earlier references</option><option value="selected">My selections</option></select><button class="pill primary" id="export">Export selections (0)</button><button class="pill" id="clear">Clear</button></div><div class="files-note">Open assets individually or copy <code>public/assets/exotic/</code> into your project. Direct GLB links use the local server; the model inspector also has an offline file picker.</div><div class="notice" role="status" id="status"></div></div></section><section class="wrap"><div id="count" class="summary" aria-live="polite"></div><div id="grid" class="grid"></div></section></main><footer class="footer"><div class="wrap"><a href="examples/model-viewer.html">Open GLB inspector</a><a href="previews/3d-models-contact-sheet.jpg">View model contact sheet</a><a href="previews/asset-pack-overview.jpg">View overview</a><a href="ASSET_MANIFEST.json">File manifest</a><p>Native-size logo derivatives require artwork review. Models are visual web assets, not CAD. Lottie production-runtime playback still needs validation in your chosen player. No fonts, remote trackers or paid-model downloads are bundled.</p></div></footer><script>
const assets=__DATA__;const selected=new Set();const grid=document.getElementById('grid');const filter=document.getElementById('category');const search=document.getElementById('search');const exp=document.getElementById('export');const status=document.getElementById('status');
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function render(){const q=search.value.toLowerCase().trim(),cat=filter.value;const data=assets.filter(a=>(cat==='all'||cat==='recommended'&&a.recommended||cat==='selected'&&selected.has(a.id)||a.category===cat)&&(!q||(a.title+' '+a.details+' '+a.id).toLowerCase().includes(q)));document.getElementById('count').textContent=`${data.length} DESIGNS SHOWN · ${selected.size} SELECTED`;exp.textContent=`Export selections (${selected.size})`;grid.innerHTML=data.map(a=>`<article class="card" data-category="${esc(a.category)}"><div class="art"><img loading="lazy" src="${esc(a.image)}" alt="${esc(a.title)} preview">${a.recommended?'<span class="badge">SHORTLIST</span>':''}${a.animation?`<button class="small play" data-play="${esc(a.id)}" aria-pressed="false">Play preview</button>`:''}</div><div class="body"><h2>${esc(a.title)}</h2><p>${esc(a.details)}</p><div class="links"><a href="${esc(a.src)}" download>Source ${esc(a.src.split('.').pop().toUpperCase())} ↓</a>${a.secondary?`<a href="${esc(a.secondary)}" download>${esc(a.secondaryLabel)} ↓</a>`:''}</div><div class="bottom"><button class="small select" data-select="${esc(a.id)}" aria-pressed="${selected.has(a.id)}">${selected.has(a.id)?'Selected ✓':'Select asset'}</button>${a.inspect?`<a class="small" href="examples/model-viewer.html?model=${encodeURIComponent('../'+a.src)}">Inspect 3D ↗</a>`:''}</div></div></article>`).join('')||'<p class="empty">No matches. Try another category or search.</p>';}
grid.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select){const id=b.dataset.select;selected.has(id)?selected.delete(id):selected.add(id);b.setAttribute('aria-pressed',selected.has(id));b.textContent=selected.has(id)?'Selected ✓':'Select asset';exp.textContent=`Export selections (${selected.size})`;status.textContent=`${selected.size} assets in your shortlist.`;if(filter.value==='selected')render();}if(b.dataset.play){const a=assets.find(x=>x.id===b.dataset.play),im=b.closest('.art').querySelector('img'),playing=b.getAttribute('aria-pressed')==='true';if(matchMedia('(prefers-reduced-motion: reduce)').matches){im.src=a.image;b.setAttribute('aria-pressed','false');b.textContent='Static preview';status.textContent='Reduced motion is enabled; showing the static poster.';return;}im.src=playing?a.image:a.animation;b.setAttribute('aria-pressed',!playing);b.textContent=playing?'Play preview':'Pause preview';}});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{if(e.matches){grid.querySelectorAll('[data-play]').forEach(b=>{const a=assets.find(x=>x.id===b.dataset.play);b.closest('.art').querySelector('img').src=a.image;b.setAttribute('aria-pressed','false');b.textContent='Play preview';});}});filter.addEventListener('change',render);search.addEventListener('input',render);document.getElementById('clear').onclick=()=>{selected.clear();status.textContent='Selection cleared.';render()};exp.onclick=()=>{if(!selected.size){status.textContent='Select at least one asset before exporting.';return}const data={project:'Exotic Event & Entertainment',instructions:'Use this as a shortlist, not as a requirement to load everything simultaneously.',assetBase:'/assets/exotic/',selections:assets.filter(a=>selected.has(a.id)).map(a=>({id:a.id,category:a.category,source:a.src,alternative:a.secondary||null}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='exotic-asset-selection.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Selection JSON exported. Give it to your coding agent with BUILD_PROMPT.md.'};render();window.exoticCatalogue={assets,selected};
</script></body></html>'''.replace('__DATA__',DATA)
(ROOT/'START_HERE.html').write_text(htmlpage)
